package com.example.classmanagement.auth;
import com.example.classmanagement.api.*; import com.example.classmanagement.security.JwtService; import com.example.classmanagement.user.*; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {record Login(@NotBlank String username,@NotBlank String password){} private final UserRepository repo;private final PasswordEncoder enc;private final JwtService jwt; public AuthController(UserRepository r,PasswordEncoder e,JwtService j){repo=r;enc=e;jwt=j;} @PostMapping("/login") public ApiResponse<?> login(@Valid @RequestBody Login x){var u=repo.findByUsername(x.username()).orElse(null);if(u==null||!enc.matches(x.password(),u.password))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.UNAUTHORIZED,"账号或密码错误");return ApiResponse.ok(java.util.Map.of("token",jwt.create(u.username),"user",java.util.Map.of("username",u.username,"role",u.role)));} @GetMapping("/me") public ApiResponse<?> me(org.springframework.security.core.Authentication a){return ApiResponse.ok(java.util.Map.of("username",a.getName(),"role",repo.findByUsername(a.getName()).orElseThrow().role));} @PostMapping("/logout") public ApiResponse<?> logout(){return ApiResponse.ok(null);} }

